/* From Uiverse.io by TaniaDou - Tags: input, remove, placeholder, cool input */
.__UIV_SCOPE__ .input-box {
  position: relative;
  max-width: 190px;
}

.__UIV_SCOPE__ .input {
  position: relative;
  width: 100%;
  padding: 1.5rem;
  background: none;
  border: solid 1.5px #9e9e9e;
  border-radius: .6rem;
  color: #9e9e9e;
  font-size: 1rem;
}

.__UIV_SCOPE__ .label {
  position: absolute;
  pointer-events: none;
  left: 1rem;
  top: .875rem;
  white-space: nowrap;
  overflow: hidden;
  line-height: 2rem;
  padding-left: 1rem;
  font-size: 1rem;
  color: #9e9e9e;
  transition: 500ms cubic-bezier(0.4,0,0.2,1);
}

.__UIV_SCOPE__ .input:focus~.label, .__UIV_SCOPE__ input:valid ~ label {
  top: -6px;
  left: -5px;
  font-size: .875rem;
  color: #9e9e9e;
}
